CREATE TABLE public.facegate_broadcast_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, storage_path text NOT NULL, media_type text NOT NULL CHECK (media_type IN ('image','video')), mime_type text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes>0), duration_seconds integer NOT NULL DEFAULT 10 CHECK(duration_seconds BETWEEN 3 AND 300), sort_order integer NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.facegate_broadcast_media TO authenticated; GRANT ALL ON public.facegate_broadcast_media TO service_role;
ALTER TABLE public.facegate_broadcast_media ENABLE ROW LEVEL SECURITY;
CREATE POLICY facegate_media_admin ON public.facegate_broadcast_media FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'director')) WITH CHECK (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'director'));
CREATE TABLE public.kiosk_commands (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), device_id text NOT NULL, kind text NOT NULL CHECK(kind IN ('power','door')), action text NOT NULL CHECK(action IN ('screen_on','screen_off','sleep','shutdown','cancel','wake','open','free','lock')), payload jsonb NOT NULL DEFAULT '{}', created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), consumed_at timestamptz, expires_at timestamptz NOT NULL DEFAULT now()+interval '2 minutes');
GRANT SELECT ON public.kiosk_commands TO authenticated; GRANT ALL ON public.kiosk_commands TO service_role;
ALTER TABLE public.kiosk_commands ENABLE ROW LEVEL SECURITY;
CREATE POLICY facegate_command_admin_read ON public.kiosk_commands FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'director'));
CREATE INDEX kiosk_commands_pending ON public.kiosk_commands(device_id,kind,created_at) WHERE consumed_at IS NULL;